         uint64_t n = 1;
         for (auto d : shape) n *= d;
         return n;
     }
+    uint64_t payload_bytes() const { return tensor_payload_bytes(*this); }
+    uint64_t offset_end() const { return offset + payload_bytes(); }
     const char* type_name() const { return ggml_type_name(type); }
 };

@@ -310,6 +314,22 @@
     uint64_t alignment() const { return alignment_; }
     const std::string& path() const { return path_; }

+    /// Validates that every tensor's payload lies within the file's data section.
+    /// Returns the first out-of-bounds tensor name, or empty string if all are valid.
+    std::string validate_tensor_bounds() const {
+        const uint64_t payload = size_ - data_start_;
+        for (const auto& t : tensors_) {
+            const uint64_t bytes = tensor_payload_bytes(t);
+            if (bytes == 0)
+                return "unknown type or non-whole-block shape for tensor '" + t.name + "'";
+            if (t.offset > payload || bytes > payload - t.offset)
+                return "tensor '" + t.name + "' payload [" + std::to_string(t.offset) + ", " +
+                       std::to_string(t.offset + bytes) + ") exceeds data section of " +
+                       std::to_string(payload) + " bytes";
+        }
+        return {};
+    }
+
     const TensorInfo* find(const std::string& name) const {
         for (const auto& t : tensors_)
             if (t.name == name) return &t;
```

